#!/usr/bin/env node
// Independent CircomlibJS verifier for vectors generated by generate_vectors.py.
// Requires circomlibjs to be installed in the current Node project.
import fs from 'node:fs';
import { buildPoseidon } from 'circomlibjs';

const path = process.argv[2] ?? 'shard_merkle_vectors.json';
const doc = JSON.parse(fs.readFileSync(path, 'utf8'));
const poseidon = await buildPoseidon();
const F = poseidon.F;
const H = (...xs) => F.toString(poseidon(xs.map(BigInt)));
const eq = (actual, expected, label) => {
  if (String(actual) !== String(expected)) {
    throw new Error(`${label}: expected ${expected}, got ${actual}`);
  }
};
eq(H(11, 22, 2026), '4108572264724763218754967574827674763137797405379838691109633427075516621983', 'known Poseidon-3 vector');
const hexChunks = (hex, size = 31) => {
  const out = [];
  for (let i = 0; i < hex.length; i += size * 2) out.push(hex.slice(i, i + size * 2));
  return out;
};
const chunkLeaf = (hex) => {
  const bytes = Buffer.from(hex, 'hex');
  if (bytes.length < 1 || bytes.length > 31) throw new Error('invalid chunk length');
  const value = bytes.length ? BigInt(`0x${bytes.toString('hex')}`) : 0n;
  return H(1, bytes.length, value);
};
const parent = (left, right) => H(2, left, right);
const buildLevels = (leaves) => {
  const levels = [leaves.map(String)];
  let current = leaves.map(BigInt);
  while (current.length > 1) {
    const next = [];
    for (let i = 0; i < current.length; i += 2) {
      const left = current[i];
      const right = i + 1 < current.length ? current[i + 1] : left;
      next.push(BigInt(parent(left, right)));
    }
    current = next;
    levels.push(current.map(String));
  }
  return levels;
};

let checked = 0;
for (const c of doc.cases) {
  const shardRoots = [];
  const globalLeaves = [];
  for (const s of c.shards) {
    const chunks = hexChunks(s.data_hex);
    if (chunks.length !== s.chunks_hex.length) throw new Error(`${c.name}: chunk count mismatch`);
    chunks.forEach((chunk, i) => eq(chunk, s.chunks_hex[i], `${c.name} shard ${s.shard_index} chunk ${i} bytes`));
    const leaves = chunks.map(chunkLeaf);
    leaves.forEach((v, i) => eq(v, s.chunk_leaf_hashes[i], `${c.name} chunk leaf ${i}`));
    const innerLevels = buildLevels(leaves);
    innerLevels.forEach((level, i) => level.forEach((v, j) => eq(v, s.inner_levels[i][j], `${c.name} inner level ${i}, node ${j}`)));
    const shardRoot = H(3, chunks.length, innerLevels.at(-1)[0]);
    eq(shardRoot, s.shard_root, `${c.name} shard root ${s.shard_index}`);
    shardRoots.push(BigInt(shardRoot));
    globalLeaves.push(BigInt(H(4, s.shard_index, shardRoot)));

    for (const p of s.proofs) {
      // Verify chunk inclusion and enforce duplicate-last sibling equality.
      let current = BigInt(chunkLeaf(p.chunk_hex));
      let index = p.chunk_index;
      let width = chunks.length;
      for (const sibText of p.chunk_siblings) {
        const sibling = BigInt(sibText);
        if (index % 2 === 0 && index + 1 >= width && sibling !== current) {
          throw new Error(`${c.name}: invalid duplicate-last inner sibling`);
        }
        current = index % 2 === 0 ? BigInt(parent(current, sibling)) : BigInt(parent(sibling, current));
        index = Math.floor(index / 2);
        width = Math.ceil(width / 2);
      }
      current = BigInt(H(3, chunks.length, current));
      eq(current, shardRoot, `${c.name} chunk proof shard root`);

      // Verify the outer proof for this shard against the generation root.
      let outer = BigInt(H(4, p.shard_index, shardRoot));
      let outerIndex = p.shard_index;
      let outerWidth = c.shard_count;
      for (const sibText of p.shard_siblings) {
        const sibling = BigInt(sibText);
        if (outerIndex % 2 === 0 && outerIndex + 1 >= outerWidth && sibling !== outer) {
          throw new Error(`${c.name}: invalid duplicate-last outer sibling`);
        }
        outer = outerIndex % 2 === 0 ? BigInt(parent(outer, sibling)) : BigInt(parent(sibling, outer));
        outerIndex = Math.floor(outerIndex / 2);
        outerWidth = Math.ceil(outerWidth / 2);
      }
      outer = BigInt(H(5, c.shard_count, outer));
      eq(outer, c.global_root, `${c.name} shard proof global root`);
      checked++;
    }
  }
  globalLeaves.forEach((v, i) => eq(v, c.global_leaf_hashes[i], `${c.name} global leaf ${i}`));
  const globalLevels = buildLevels(globalLeaves);
  globalLevels.forEach((level, i) => level.forEach((v, j) => eq(v, c.global_levels[i][j], `${c.name} global level ${i}, node ${j}`)));
  const globalRoot = H(5, shardRoots.length, globalLevels.at(-1)[0]);
  eq(globalRoot, c.global_root, `${c.name} global root`);
  console.log(`PASS ${c.name}: ${c.shard_count} shards × ${c.shard_size_bytes} bytes; root=${globalRoot}`);
}
console.log(`All ${doc.cases.length} cases passed; checked ${checked} chunk proofs.`);
